export function startGame(): void {
  const gameBoard: number[][] = Array.from({ length: 10 }, () => Array(12).fill(0));
  const playerShip: { x: number; y: number; health: number } = { x: 5, y: 9, health: 3 };
  const enemies: { x: number; y: number; health: number; speed: number }[] = [];
  const bullets: { x: number; y: number; direction: 'up' | 'down' }[] = [];
  let isRunning: boolean = true;
  let timer: number = 0;
  let score: number = 0;

  function init(): void {
    timer = 0;
    score = 0;
    isRunning = true;
    enemies.length = 0;
    bullets.length = 0;
    playerShip.x = 5;
    playerShip.y = 9;
    playerShip.health = 3;
    for (let i = 0; i < 5; i++) {
      const x = 1 + i * 2;
      const y = 1;
      enemies.push({ x, y, health: 1, speed: 1 });
    }
  }

  function update(dt: number): void {
    if (!isRunning) return;
    timer += dt;
    if (timer >= 0.5) {
      timer = 0;
      const enemy = enemies[0];
      if (enemy) {
        enemy.y++;
        if (enemy.y >= 8) {
          isRunning = false;
          return;
        }
      }
    }
    for (let i = 0; i < bullets.length; i++) {
      const b = bullets[i];
      if (!b) continue;
      b.y += (b.direction === 'up' ? 1 : -1) * 2;
      if (b.y < 0 || b.y > 10) {
        bullets.splice(i, 1);
        continue;
      }
      const hit = enemies.find(e => e.x === b.x && e.y === b.y);
      if (hit) {
        hit.health--;
        if (hit.health <= 0) {
          enemies.splice(enemies.indexOf(hit), 1);
          bullets.splice(i, 1);
          score++;
          continue;
        }
        bullets.splice(i, 1);
        continue;
      }
    }
  }

  function render(): void {
    const canvas = document.getElementById('gameCanvas') as HTMLCanvasElement;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < 10; i++) {
      for (let j = 0; j < 12; j++) {
        ctx.fillStyle = gameBoard[i][j] ? '#000' : '#fff';
        ctx.fillRect(j * 20, i * 20, 20, 20);
      }
    }
    ctx.fillStyle = '#fff';
    ctx.fillRect(playerShip.x * 20, playerShip.y * 20, 20, 20);
    for (const enemy of enemies) {
      ctx.fillStyle = '#f00';
      ctx.fillRect(enemy.x * 20, enemy.y * 20, 20, 20);
    }
    for (const b of bullets) {
      ctx.fillStyle = b.direction === 'up' ? '#0f0' : '#00f';
      ctx.fillRect(b.x * 20, b.y * 20, 20, 20);
    }
    ctx.fillStyle = '#fff';
    ctx.font = '12px Arial';
    ctx.fillText(`Score: ${score}`, 10, 20);
  }

  function handleInput(event: KeyboardEvent): void {
    if (!isRunning) return;
    const key = event.key.toLowerCase();
    if (key === 'w') {
      bullets.push({ x: playerShip.x, y: playerShip.y, direction: 'up' });
    } else if (key === 's') {
      bullets.push({ x: playerShip.x, y: playerShip.y, direction: 'down' });
    }
  }

  function main(): void {
    const canvas = document.getElementById('gameCanvas') as HTMLCanvasElement;
    if (!canvas) return;
    canvas.width = 240;
    canvas.height = 200;
    const timer = setInterval(() => {
      update(0.016);
      render();
      handleInput(event);
    }, 16);
  }

  init();
  main();
}

