export interface GameState {
  playerShip: { health: number; position: { x: number; y: number } };
  enemies: { health: number; position: { x: number; y: number } }[];
  bullets: { type: 'player' | 'enemy'; position: { x: number; y: number } }[];
  score: number;
  lives: number;
  level: number;
  gameRunning: boolean;
  gameOver: boolean;
}

export function initializeGameState(): GameState {
  return {
    playerShip: { health: 100, position: { x: 400, y: 600 } },
    enemies: Array.from({ length: 10 }, () => ({
      health: 100,
      position: { x: Math.random() * 700, y: 50 + Math.random() * 100 },
    })),
    bullets: [],
    score: 0,
    lives: 3,
    level: 1,
    gameRunning: true,
    gameOver: false,
  };
}

export function updateGameState(state: GameState, deltaTime: number): void {
  if (!state.gameRunning) return;

  // Player bullet logic
  state.bullets.forEach((bullet, index) => {
    if (bullet.type === 'player') {
      bullet.position.y -= 5 * deltaTime;
      if (bullet.position.y < 0) {
        state.bullets.splice(index, 1);
      } else {
        // Check for enemy collision
        state.enemies.forEach((enemy, enemyIndex) => {
          if (enemy.position.y > 650) {
            state.enemies.splice(enemyIndex, 1);
            state.score += 10;
            state.bullets.splice(index, 1);
          }
        });
      }
    } else if (bullet.type === 'enemy') {
      bullet.position.y += 3 * deltaTime;
      if (bullet.position.y > 700) {
        state.bullets.splice(index, 1);
      } else {
        // Check for player collision
        if (Math.abs(bullet.position.x - state.playerShip.position.x) < 30 && bullet.position.y > state.playerShip.position.y - 20) {
          state.playerShip.health -= 20;
          state.bullets.splice(index, 1);
          if (state.playerShip.health <= 0) {
            state.gameRunning = false;
            state.gameOver = true;
          }
        }
      }
    }
  });

  // Enemy movement
  state.enemies.forEach((enemy, index) => {
    enemy.position.y += 2 * deltaTime;
    if (enemy.position.y > 650) {
      state.enemies.splice(index, 1);
    } else {
      // Check for edge collision
      if (enemy.position.x < 0 || enemy.position.x > 700) {
        enemy.position.x = enemy.position.x < 0 ? 0 : 700;
        enemy.position.x += 2 * deltaTime;
      }
    }
  });

  // Player ship input
  const ship = state.playerShip;
  if (input.keyboardDown('ArrowUp')) {
    ship.position.y -= 5 * deltaTime;
  }
  if (input.keyboardDown('ArrowDown')) {
    ship.position.y += 5 * deltaTime;
  }
  if (input.keyboardDown('ArrowLeft')) {
    ship.position.x -= 5 * deltaTime;
  }
  if (input.keyboardDown('ArrowRight')) {
    ship.position.x += 5 * deltaTime;
  }
  if (input.keyboardDown(' ')) {
    state.bullets.push({ type: 'player', position: { x: ship.position.x + 20, y: ship.position.y } });
  }
}

