export function aiOpponentStrategy(state: GameState, deltaTime: number): void {
  const aiShip = { health: 100, position: { x: 350, y: 200 } };
  const aiBullets: { type: 'ai'; position: { x: number; y: number } }[] = [];

  // Enemy movement
  state.enemies.forEach((enemy, index) => {
    enemy.position.y += 2 * deltaTime;
    if (enemy.position.y > 650) {
      state.enemies.splice(index, 1);
    } else {
      // Check for edge collision
      if (enemy.position.x < 0 || enemy.position.x > 700) {
        enemy.position.x = enemy.position.x < 0 ? 0 : 700;
        enemy.position.x += 2 * deltaTime;
      }
    }
  });

  // Player ship input
  const ship = state.playerShip;
  if (ship.position.y < 100) ship.position.y = 100;
  if (ship.position.y > 600) ship.position.y = 600;

  // AI bullet logic
  if (Math.random() < 0.1) {
    aiBullets.push({ type: 'ai', position: { x: aiShip.position.x + 20, y: aiShip.position.y } });
  }

  // Player bullet logic
  state.bullets.forEach((bullet, index) => {
    if (bullet.type === 'player') {
      bullet.position.y -= 5 * deltaTime;
      if (bullet.position.y < 0) {
        state.bullets.splice(index, 1);
      } else {
        // Check for enemy collision
        state.enemies.forEach((enemy, enemyIndex) => {
          if (enemy.position.y > 650) {
            state.enemies.splice(enemyIndex, 1);
            state.score += 10;
            state.bullets.splice(index, 1);
          } else if (Math.abs(bullet.position.x - enemy.position.x) < 30 && bullet.position.y > enemy.position.y - 20) {
            enemy.health -= 20;
            state.bullets.splice(index, 1);
            if (enemy.health <= 0) {
              state.enemies.splice(enemyIndex, 1);
              state.score += 50;
            }
          }
        });
      }
    } else if (bullet.type === 'ai') {
      bullet.position.y += 3 * deltaTime;
      if (bullet.position.y > 700) {
        state.bullets.splice(index, 1);
      } else {
        // Check for player collision
        if (Math.abs(bullet.position.x - ship.position.x) < 30 && bullet.position.y > ship.position.y - 20) {
          ship.health -= 20;
          state.bullets.splice(index, 1);
          if (ship.health <= 0) {
            state.gameRunning = false;
            state.gameOver = true;
          }
        }
      }
    }
  });

  // Update the state
  state.playerShip = ship;
  state.bullets = aiBullets;
}

